  d=event(d['state'],'voice_permissions');check('permission control opens only the app permission surface',d['effect']=={'kind':'microphone_permissions'}and not d['state'].get('voice_consent'));d=event(d['state'],'phone_access_status',dict(device={'microphone_granted':False}));check('platform denial is shown without claiming a missing microphone','not allowed'in fields(d)['microphone_permission']['value']);d=event(d['state'],'phone_access_status',dict(device={'microphone_granted':True}));check('platform permission observation reaches its visible control','is allowed'in fields(d)['microphone_permission']['value'])
  d=event(d['state'],'close');d=event(d['state'],'voice_settings');check('reopening settings retains saved capture values',fields(d)['voice_threshold']['value']=='700'and fields(d)['voice_background']['value']=='true');saved=copy.deepcopy(d['state']['voice_settings'])
  for inputs in[{'voice_silence_ms':'299'},{'voice_threshold':'5001'},{'voice_max_seconds':'31'},{'voice_threshold':'not-a-number'},{'voice_threshold':True},{'voice_threshold':''},{'voice_background':'true'}]:
   d=event(d['state'],'voice_settings');d=event(d['state'],'voice_settings_save',inputs);check('invalid preferences preserve the saved configuration '+str(inputs),d['effect']is None and d['state']['voice_settings']==saved and d['state'].get('notice_error'))
  d=event(initial,'voice_settings_save');check('saving outside its settings dialog cannot change preferences',d['effect']is None and not d['state'].get('voice_settings'))
  d=event(initial,'voice_settings');d=event(d['state'],'voice_settings_save',dict(voice_silence_ms=600,voice_threshold=900,voice_max_seconds=10));check('typed integer settings save their actual values',d['effect']is None and d['state']['voice_settings']['threshold']==900 and d['state']['voice_settings']['silence_ms']==600 and d['state']['voice_settings']['max_seconds']==10)
  for fmt in['chat','local','messages','content']:
   d=event(configured(fmt),'voice_settings');d=event(d['state'],'voice_settings_save',dict(voice_silence_ms='300',voice_threshold='700',voice_max_seconds='5',voice_background=True,voice_interruption=False));n=len(requests);d=event(d['state'],'voice_open_review');check(fmt+' open-microphone button reaches an explicit review without capture',d['effect']is None and fields(d)['voice_open']['value']=='true'and len(requests)==n);d=event(d['state'],'voice_consent');capture=copy.deepcopy(d['effect']);check(fmt+' review starts actual capture with saved preferences and background choice',capture['kind']=='voice_listen'and capture['voice_background']and d['state']['voice_settings']==cfg)
   d=event(d['state'],'voice_settings');check(fmt+' opening settings retires only its voice session',not d['state']['voice_open']and d['effect']['voice_only']and d['state']['dialog']=='voice_settings');late=event(d['state'],'voice_audio_start',dict(voice_session=capture['voice_session'],voice_audio_ticket=capture['voice_audio_ticket']));check(fmt+' old microphone callback cannot rearm capture after settings',late['state']==d['state']and late['effect']is None)
   d=event(d['state'],'voice_review');check(fmt+' manual review does not silently select background capture',fields(d)['voice_open']['value']=='false'and fields(d)['voice_background']['value']=='false');d=event(d['state'],'close');d=event(d['state'],'voice_open_review');check(fmt+' cancelled manual review preserves saved background preference',fields(d)['voice_background']['value']=='true');d=event(d['state'],'voice_consent');d=utterance(d);d=exchange(d);ticket=d['state']['model_expected'];d=event(d['state'],'voice_settings');check(fmt+' opening settings during a primary reply preserves that model owner',d['state']['busy']and d['state']['model_expected']==ticket and not d['state']['voice_open']);d=event(d['state'],'voice_settings_save',dict(voice_threshold='800'));check(fmt+' saving preferences preserves the in-flight primary reply',d['state']['busy']and d['state']['model_expected']==ticket);d=model(d,fmt,'Primary text retained while editing microphone settings.');check(fmt+' primary reply completes without starting unreviewed speech',d['effect']is None and not d['state']['busy']and any('Primary text retained'in m.get('content','')for c in d['state']['chats']for m in c['messages']))
   d=event(d['state'],'voice_open_review');d=event(d['state'],'voice_consent');session=d['effect']['voice_session'];lease=d['effect']['voice_lease_ms'];d=utterance(d);check(fmt+' configured recognition receives real microphone data',d['effect']['purpose'].startswith('service_request:'));d=exchange(d);check(fmt+' recognized text reaches ordinary conversation',d['effect']['purpose']=='model'and'Question from the microphone.'in d['effect']['wire']);d=model(d,fmt,'Spoken answer through configured services.');d=exchange(d);e=d['effect'];check(fmt+' real synthesis result reaches owned playback',e['kind']=='media_preview'and e['media_kind']=='audio'and e['voice_session']==session);owner=dict(voice_session=session,voice_playback_ticket=e['voice_playback_ticket']);d=event(d['state'],'voice_playback_start',owner);d=event(d['state'],'voice_playback_result',dict(owner,completed=True));check(fmt+' completed spoken reply returns to the same bounded listening session',d['effect']['kind']=='voice_listen'and d['effect']['voice_background']and d['effect']['voice_session']==session and 0<d['effect']['voice_lease_ms']<=lease);d=event(d['state'],'voice_settings');check(fmt+' returning to settings stops the new listener without removing text',not d['state']['voice_open']and any('Spoken answer through configured services.'in m.get('content','')for c in d['state']['chats']for m in c['messages']))
